/** A shape whose own symbol names it, so it reaches the O7 shortcut unaided. */
export interface Widget {
    id: string;
}

/** An alias over an object literal. The type carries `__type` and the name sits on the alias. */
export type WidgetPair = {
    left: Widget;
    right: Widget;
};

/** An alias over a call signature: named, and with no members to copy. */
export type Formatter = (value: string) => string;
